-- ====================================================================
-- 京都府 観光施設 3空間感性データベース (1428地点)
-- 元データ: 260002kankoushisetsu.csv (京都府オープンデータ)
-- 生成方式: ルールベース（パターンA / 空間定義に基づく参照列分離）
-- ====================================================================

-- ① 場所と位置座標のデータベース (spots: 1428地点)
CREATE TABLE spots (
    観光地名 VARCHAR(100) PRIMARY KEY,
    緯度 DOUBLE,
    経度 DOUBLE
);


-- ② 活動空間マトリクス (観光地＝行、印象語18語＝列)
CREATE TABLE space_matrix (
    観光地名 VARCHAR(100) PRIMARY KEY,
    `楽しい` INT, `賑やかな` INT, `はしゃぐ` INT, `ワイワイ` INT, `ワクワク` INT, `ゆっくり` INT, `落ち着いた` INT, `癒す` INT, `まったり` INT, `ゆったりとした` INT, `晴れる気がする` INT, `田舎` INT, `きれい` INT, `おいしい` INT, `文化的な` INT, `歴史的な` INT, `面白い` INT, `非日常的な` INT,
    FOREIGN KEY (観光地名) REFERENCES spots(観光地名)
);


-- ③ 移動空間マトリクス (観光地＝行、印象語19語＝列)
CREATE TABLE move_matrix (
    観光地名 VARCHAR(100) PRIMARY KEY,
    `スムーズな` INT, `賑やかな` INT, `単調な` INT, `道に迷わない` INT, `開放的な` INT, `交通手段が便利` INT, `勾配がある` INT, `殺風景な` INT, `歩行空間にゆとりがある` INT, `道幅が広い` INT, `歴史的な` INT, `緑豊かな` INT, `安心感がある` INT, `非日常的な` INT, `落ち着いた` INT, `きれい` INT, `快適` INT, `見晴らしの良い` INT, `静寂な` INT,
    FOREIGN KEY (観光地名) REFERENCES spots(観光地名)
);


-- ④ 滞在空間マトリクス (観光地＝行、印象語17語＝列)
CREATE TABLE stay_matrix (
    観光地名 VARCHAR(100) PRIMARY KEY,
    `快適` INT, `荘厳な` INT, `落ち着いた` INT, `非日常的な` INT, `洋風な` INT, `和風な` INT, `きれい` INT, `モダンな` INT, `開放的な` INT, `こぢんまりした` INT, `平坦な` INT, `静寂な` INT, `緑豊かな` INT, `明るい` INT, `見晴らしの良い` INT, `雨が避けられる` INT, `賑やかな` INT,
    FOREIGN KEY (観光地名) REFERENCES spots(観光地名)
);

